const transcript =
  "आज मैंने सब्जियां बेचकर 450 रुपये कमाए। मंडी जाने के लिए 120 रुपये खर्च हुए और पैकिंग के लिए 80 रुपये दिए।";

const ledgerEntries = [
  {
    date: "15 Jul 2026",
    type: "Income",
    category: "Vegetable Sales",
    amount: 450,
    description: "Vegetables sold in the local market"
  },
  {
    date: "15 Jul 2026",
    type: "Expense",
    category: "Transport",
    amount: 120,
    description: "Travel to the mandi"
  },
  {
    date: "15 Jul 2026",
    type: "Expense",
    category: "Packaging",
    amount: 80,
    description: "Packaging material"
  }
];

const income = ledgerEntries
  .filter(entry => entry.type === "Income")
  .reduce((total, entry) => total + entry.amount, 0);

const expenses = ledgerEntries
  .filter(entry => entry.type === "Expense")
  .reduce((total, entry) => total + entry.amount, 0);

return {
  transcript,
  ledgerEntries,
  income,
  expenses,
  surplus: income - expenses,
  status: "Voice processed successfully"
};

